chapters.code_example:
.product-card {
  border: 1px solid #dbe2ea;
  padding: 16px;
}

.product-card h2 {
  margin-bottom: 8px;
}

#featured-product {
  border-color: #0ea5e9;
}

.signup-form label {
  font-weight: 600;
}

.signup-form > input {
  display: block;
  margin-bottom: 12px;
}

input + small {
  color: #64748b;
}

input[type="email"] {
  border-color: #38bdf8;
}

button[aria-expanded="true"] {
  background: #082f49;
  color: #f8fafc;
}

[data-status="warning"] {
  color: #b45309;
}
